const repo=new M.Repository({async get(k){const raw=localStorage.getItem(k);return raw?JSON.parse(raw):null},async set(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{throw Error('本地存储不足或不可用，请下载重要作品后清理记录。此次操作未保存。')}},async remove(k){localStorage.removeItem(k)}});
