function updateNav(){const admin=current.startsWith('admin-');$('#nav').classList.toggle('hidden',admin||current==='splash');$('#nav').innerHTML=[['home','首页','⌂'],['library','作品库','藏'],['booking','预约','约'],['profile','我的','我']].map(([id,n,g])=>`<a href="#${id}" class="${current===id?'active':''}"><span class="nav-icon">${g}</span>${n}</a>`).join('');document.body.classList.toggle('admin-mode',admin);document.body.classList.toggle('studio-mode',current==='write'||current==='paint');document.body.classList.toggle('splash-mode',current==='splash')}
async function render(){const serial=++generation;const [route,query='']=location.hash.slice(1).split('?');const previous=current;current=route||'splash';if(current==='write'&&previous!=='write'){musicWanted=true;musicPausedByUser=false}if(!['experts','booking'].includes(current))assistCase=null;const params=new URLSearchParams(query);if(engine){engine.destroy();engine=null;stampEditing=false}if(current!=='write'){musicWanted=false;pauseWritingMusic()}clearInterval(carousel);clearInterval(photoCarousel);updateNav();$('#main').scrollTop=0;const pages={splash,home,write:()=>studio('write'),paint:()=>studio('paint'),test:quiz,result:()=>result(params.get('id')),chat,library,booking,experts,profile,'admin-risk':adminRisk,'admin-booking':adminBooking,'admin-experts':adminExperts,'admin-works':adminWorks};if(!pages[current]){navigate('home');return}const html=await pages[current]();if(serial!==generation)return;$('#main').innerHTML=html;$('#main').dataset.route=current;if(current==='write'||current==='paint'){mountCanvas(current);artReference(current);if(current==='write'){syncMusicButton();if(musicWanted&&!musicPausedByUser)playWritingMusic()}}if(current==='result')mountRadar(params.get('id'));if(current==='chat'){$('#chatLog').scrollTop=$('#chatLog').scrollHeight}if(current==='home'){mountEventSwipe();mountBookingPhotos()}}
