let photoCarousel=null,photoIndex=0;
function bookingPhotos(){return '<article class="module booking-module"><a class="booking-entry" href="#booking"><span class="glyph">约</span><h3>线下活动预约</h3><p>团辅与专家预约</p></a><div class="booking-photos" id="bookingPhotos" role="region" aria-roledescription="轮播图" aria-label="线下活动照片"><div class="photo-track">'+[1,2,3,4].map((n,i)=>'<a class="photo-slide" href="#booking" tabindex="'+(i===photoIndex?'0':'-1')+'" aria-label="线下活动照片 '+n+'，了解与预约"><img src="../assets/activity-photo-'+n+'.jpg" alt="线下活动照片 '+n+'" width="900" height="600" draggable="false" decoding="async"></a>').join('')+'</div></div><div class="photo-dots">'+[1,2,3,4].map((n,i)=>'<button type="button" data-action="photo-slide" data-id="'+i+'" aria-label="查看第 '+n+' 张活动照片"></button>').join('')+'</div></article>'}
function startPhotoCarousel(){clearInterval(photoCarousel);if(current==='home'&&!document.hidden)photoCarousel=setInterval(()=>showPhoto(photoIndex+1),4000)}
function showPhoto(index,restart=false){photoIndex=(index+4)%4;const track=$('.photo-track');if(!track)return;track.style.transform='translateX(-'+photoIndex*100+'%)';$$('.photo-slide').forEach((e,i)=>{e.tabIndex=i===photoIndex?0:-1;e.setAttribute('aria-hidden',String(i!==photoIndex))});$$('[data-action="photo-slide"]').forEach((e,i)=>{e.classList.toggle('active',i===photoIndex);e.setAttribute('aria-pressed',String(i===photoIndex))});if(restart)startPhotoCarousel()}
function mountBookingPhotos(){const box=$('#bookingPhotos');if(!box)return;let start=null,suppress=0;box.addEventListener('pointerdown',e=>{if(!e.isPrimary||e.button!==0)return;start={id:e.pointerId,x:e.clientX,y:e.clientY,horizontal:false};clearInterval(photoCarousel)});box.addEventListener('pointermove',e=>{if(!start||e.pointerId!==start.id)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(!start.horizontal&&Math.abs(dx)>12&&Math.abs(dx)>Math.abs(dy)*1.4){start.horizontal=true;box.setPointerCapture(e.pointerId)}});box.addEventListener('pointerup',e=>{if(!start||e.pointerId!==start.id)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(start.horizontal){suppress=Date.now()+450;if(Math.abs(dx)>=35&&Math.abs(dx)>Math.abs(dy)*1.4)showPhoto(photoIndex+(dx<0?1:-1))}start=null;startPhotoCarousel()});box.addEventListener('pointercancel',()=>{start=null;startPhotoCarousel()});box.addEventListener('lostpointercapture',()=>{if(start){start=null;startPhotoCarousel()}});box.addEventListener('click',e=>{if(Date.now()<suppress){e.preventDefault();e.stopImmediatePropagation()}},true);box.addEventListener('dragstart',e=>e.preventDefault());showPhoto(photoIndex);startPhotoCarousel()}
document.addEventListener('visibilitychange',()=>{if(document.hidden)clearInterval(photoCarousel);else startPhotoCarousel()});window.addEventListener('pagehide',()=>clearInterval(photoCarousel));

function home(){const greeting=M.greetings[Math.floor(Date.now()/60000)%M.greetings.length];return`<div class="welcome-art"><div class="eyebrow">让笔墨，成为心情的容器</div><h1 class="greeting">${greeting}</h1><p class="safety-small">本工具为美育情绪辅助，不构成心理诊断，严重情绪问题请寻求专业帮助。</p></div><div class="section-head"><h2>此刻，从心出发</h2><span class="tiny">五种方式 · 照见自己</span></div><div class="modules">${[['test','觉','情绪自测','美育觉察与 PHQ-9'],['write','书','正念书法书写','随息落笔，一笔安然'],['paint','墨','水墨情绪创作','用颜色与留白表达'],['chat','伴','AI 情绪陪伴对话','听见感受，陪伴表达'],['booking','约','线下活动预约','团辅与专家预约']].map(([p,g,t,s])=>p==='booking'?bookingPhotos():`<a class="module" href="#${p}"><div><span class="glyph">${g}</span><h3>${t}</h3><p>${s}</p></div></a>`).join('')}</div><div class="section-head"><h2>线下，一起慢下来</h2><span class="tiny">活动预告</span></div><div class="event-banner" id="eventBanner">${eventCard(state().activities[eventIndex%state().activities.length])}</div><div class="event-dots">${state().activities.map((_,i)=>`<button aria-label="查看活动 ${i+1}" class="${i===eventIndex?'active':''}" data-action="event" data-id="${i}"></button>`).join('')}</div>`}
function studio(kind){const write=kind==='write';return`<section class="studio"><div class="studio-top"><h1>${write?'正念书法书写':'水墨情绪创作'}</h1>${write?button(musicPlaying?'Ⅱ 暂停音乐':'♫ 播放音乐','music',null,'small'):button('创作说明','paint-info',null,'small')}</div><div class="reference-entry">${button(write?'书法鉴赏与参考':'国画鉴赏与参考','art-reference',kind,'small')}</div><p class="studio-guide">${write?M.guides[0]:'随心画，无对错，笔墨即心情'}</p>${write?`<div class="row"><label class="tiny" for="grid">格线</label><select id="grid" style="font-size:12px;min-height:32px;padding:4px;max-width:110px"><option>米字格</option><option>田字格</option><option>无格</option></select>${button('切换为滚动','scroll-mode',null,'small')}</div><div class="studio-scroll locked" id="paperScroll"><canvas id="drawing" class="draw-canvas" aria-label="长幅书法画布，切换滚动可移动纸面"></canvas></div>`:`<div class="paint-paper"><canvas id="drawing" class="draw-canvas" aria-label="水墨创作画布"></canvas></div>`}<div class="tools"><label for="brush">${write?'笔触':'画笔'}<select id="brush">${options(write?M.calligraphyBrushes:M.paintingBrushes,write?1:0)}</select></label><label for="color">${write?'墨色':'颜料'}<select id="color">${options(write?['浓墨','中墨','淡墨']:['纯墨黑','青灰','赭石','黛蓝'],0)}</select></label><div class="size-control"><label for="size">大小</label><input id="size" type="range" min="3" max="30" value="${write?11:14}"><output id="sizeOut">${write?11:14}</output></div></div>${!write?`<div class="material-row">${['远山','竹叶','云朵','月影'].map(n=>button(n,'material',n,'small')).join('')}</div><p class="tiny">选素材后，在画布上拖动并松手放置。</p>`:''}<div class="tool-actions">${button('↶ 撤销','undo')}${!write?button('↷ 恢复','redo'):''}${button('清空','clear')}${button('裁切纸张','paper-crop')}${write?button('加盖印章','stamp'):button('橡皮擦','eraser')}${button('保存作品','save-art',null,'primary')}</div></section>`}

function showInkPresentation(){
 const work=engine.base,crop=MorunInkReveal.findInkBounds(work);closeModal();
 const d=modal(`<section class="ink-film"><div class="ink-film-head"><div><span class="eyebrow">墨润心源</span><h2>落笔成境</h2></div>${button('跳过动画','ink-library',null,'small')}</div><div class="ink-film-stage"><canvas id="inkRevealCanvas" aria-label="水墨动画，将刚刚保存的书法作品融入山水画面"></canvas></div><div class="ink-film-bottom"><p id="inkCaption" aria-live="polite">一滴墨，慢慢展开。</p><p class="tiny">你的作品已收藏</p><div class="ink-film-actions">${button('再赏一遍','ink-replay',null,'small')}${button('继续书写','ink-continue',null,'small')}${button('查看作品 →','ink-library',null,'primary small')}</div></div></section>`);d.classList.add('ink-cinema');
 const canvas=$('#inkRevealCanvas'),ctx=canvas.getContext('2d'),reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 inkPresentation={canvas,ctx,work,crop,frame:0,elapsed:0,done:false,reduced};resizeInkPresentation();
 const landscape=new Image();landscape.onload=()=>{if(inkPresentation&&inkPresentation.canvas===canvas){inkPresentation.scene.landscape=landscape;inkPresentation.scene.draw(inkPresentation.elapsed)}};landscape.src='../assets/home-landscape.jpg';
 runInkPresentation(true);
}
function resizeInkPresentation(){const p=inkPresentation;if(!p)return;const box=p.canvas.getBoundingClientRect(),dpr=Math.min(2,window.devicePixelRatio||1);p.canvas.width=Math.round(box.width*dpr);p.canvas.height=Math.round(box.height*dpr);p.ctx.setTransform(dpr,0,0,dpr,0,0);const landscape=p.scene?.landscape;p.scene=new MorunInkReveal.Scene({ctx:p.ctx,width:box.width,height:box.height,work:p.work,crop:p.crop,landscape});p.scene.draw(p.elapsed)}
function runInkPresentation(replay=false){const p=inkPresentation;if(!p)return;cancelAnimationFrame(p.frame);if(replay){p.elapsed=0;p.done=false;$('#modal').classList.remove('ink-finished')}p.started=performance.now()-p.elapsed;
 const tick=()=>{if(inkPresentation!==p)return;p.elapsed=p.reduced?MorunInkReveal.duration:Math.min(MorunInkReveal.duration,performance.now()-p.started);p.done=p.scene.draw(p.elapsed);$('#inkCaption').textContent=p.done?'让这一刻，慢慢沉淀。':p.elapsed<2200?'一滴墨，慢慢展开。':'你的笔墨，正在成境。';if(p.done){$('#modal').classList.add('ink-finished')}else p.frame=requestAnimationFrame(tick)};tick();
}
$('#modal').addEventListener('close',()=>{if(!$('#modal').open)stopInkPresentation()});
window.addEventListener('resize',resizeInkPresentation);
document.addEventListener('visibilitychange',()=>{const p=inkPresentation;if(!p||p.done)return;if(document.hidden)cancelAnimationFrame(p.frame);else runInkPresentation()});

function point(e){const r=$('#drawing').getBoundingClientRect();return{x:(e.clientX-r.left)*engine.width/r.width,y:(e.clientY-r.top)*engine.height/r.height,t:Date.now(),pressure:e.pointerType==='pen'?e.pressure:0}}
function mountCanvas(kind){if(kind==='write'){const group=document.createElement('div');group.className='studio-top-actions';group.append($('.reference-entry .btn'),$('[data-action=music]'));$('.studio-top').append(group);$('.reference-entry').remove()}const canvas=$('#drawing'),width=Math.round(canvas.parentElement.clientWidth-2),height=kind==='write'?Math.round(width*3.2):width;canvas.width=width;canvas.height=height;canvas.style.height=height+'px';engine=new B.Brush(canvas,{kind,width,height,resizeCanvas(w,h){canvas.width=w;canvas.height=h;canvas.style.width=w+'px';canvas.style.height=h+'px';canvas.parentElement.style.width=(w+2)+'px';canvas.parentElement.style.marginLeft='auto';canvas.parentElement.style.marginRight='auto';if(kind==='paint'){canvas.parentElement.style.height=(h+2)+'px';canvas.parentElement.style.maxHeight='none';canvas.parentElement.style.aspectRatio='auto'}},makeCanvas(w,h){const c=document.createElement('canvas');c.width=w;c.height=h;return c},raf:fn=>requestAnimationFrame(fn),cancel:id=>cancelAnimationFrame(id)});engine.configure({brush:kind==='write'?1:0,size:kind==='write'?11:14});let down=false,dragging=false;
 canvas.addEventListener('pointerdown',e=>{if(canvas.classList.contains('scrollable'))return;e.preventDefault();canvas.setPointerCapture(e.pointerId);down=true;dragging=!!engine.drag;if(dragging){const p=point(e);engine.moveMaterial(p.x,p.y);engine.render()}else engine.begin(point(e))});canvas.addEventListener('pointermove',e=>{if(!down)return;e.preventDefault();if(dragging){const p=point(e);engine.moveMaterial(p.x,p.y);engine.render()}else{const events=e.getCoalescedEvents?.();for(const v of events?.length?events:[e])engine.move(point(v))}});const end=e=>{if(!down)return;down=false;if(dragging){const p=point(e);if(stampEditing){engine.moveMaterial(p.x,p.y);engine.render()}else engine.placeMaterial(p.x,p.y)}else engine.end()};canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',()=>{down=false;engine.end()});
 $('#brush').onchange=e=>{engine.configure({brush:+e.target.value,eraser:false});$$('[data-action=eraser]').forEach(b=>b.classList.remove('primary'))};$('#color').onchange=e=>engine.configure({color:(kind==='write'?M.inkColors:M.paintingColors)[+e.target.value]});$('#size').oninput=e=>{engine.configure({size:+e.target.value});$('#sizeOut').textContent=e.target.value};if($('#grid'))$('#grid').onchange=e=>{engine.grid=e.target.value;engine.render()};
}


let stampEditing=false;
function finishStampPreview(){stampEditing=false;engine.drag=null;engine.render();$('.studio')?.classList.remove('stamp-editing');$('#stampPanel')?.remove()}
function startStampPreview(text){engine.previewSeal(text);stampEditing=true;$('#drawing').classList.remove('scrollable');$('#paperScroll').classList.add('locked');$('[data-action=scroll-mode]').textContent='切换为滚动';$('#stampPanel')?.remove();$('.studio').classList.add('stamp-editing');const scroll=$('#paperScroll');engine.moveMaterial(engine.width*.7,scroll.scrollTop+Math.min(scroll.clientHeight*.5,engine.height*.5));engine.render();const panel=document.createElement('div');panel.id='stampPanel';panel.className='stamp-panel';panel.innerHTML='<p class="tiny">点按或拖动印章选择位置，调整大小后确认盖印。</p><div class="stamp-controls"><label for="stampSize">印章大小</label><input id="stampSize" type="range" min="20" max="'+Math.floor(Math.min(2,(engine.width-4)/50,(engine.height-4)/54)*100)+'" value="'+Math.round(engine.drag.size*100)+'"><output id="stampSizeOut">'+Math.round(engine.drag.size*100)+'%</output>'+button('取消','stamp-cancel',null,'small')+button('确认盖印','stamp-confirm',null,'small primary')+'</div>';$('.tool-actions').before(panel);$('#stampSize').oninput=e=>{engine.resizeSeal(Number(e.target.value)/100);$('#stampSizeOut').textContent=Math.round(engine.drag.size*100)+'%'}}

let paperCrop=null;
function openPaperCrop(){
 if(!engine)return;if(engine.drag)throw Error('请先在画布上放置素材');engine.finish();engine.render();paperCrop=new B.CropSelection(engine.width,engine.height);
 const scale=Math.min(1,Math.min(300,innerWidth-80)/engine.width,Math.min(300,innerHeight*.38)/engine.height);
 modal('<div class="modal-head"><h2>裁切纸张</h2>'+button('取消','close',null,'small')+'</div><p class="sub">拖动四角调整大小，拖动选框移动位置。</p><div class="crop-presets">'+[['full','整张'],['1','方形'],['1.5','横幅'],['0.667','竖幅']].map(([id,n])=>button(n,'crop-ratio',id,'small')).join('')+'</div><div class="crop-stage" id="cropStage" style="width:'+Math.round(engine.width*scale)+'px;height:'+Math.round(engine.height*scale)+'px"><img src="'+engine.canvas.toDataURL('image/png')+'" alt="纸张裁切预览" draggable="false"><div class="crop-selection" id="cropSelection" data-handle="move">'+['nw','ne','sw','se'].map(h=>'<span class="crop-handle '+h+'" data-handle="'+h+'"></span>').join('')+'</div></div><div class="crop-sliders"><label>宽 <input id="cropWidth" type="range" min="'+Math.ceil(paperCrop.minW*100)+'" max="100" value="100"></label><label>高 <input id="cropHeight" type="range" min="'+Math.ceil(paperCrop.minH*100)+'" max="100" value="100"></label></div><p class="tiny" id="cropSize"></p><p class="tiny">选框外的笔迹将被裁去，可用撤销恢复整张纸。</p><div class="actions">'+button('取消','close')+button('确认裁切','crop-confirm',null,'primary')+'</div>');
 const stage=$('#cropStage'),point=e=>{const r=stage.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height}};
 stage.onpointerdown=e=>{const handle=e.target.closest('[data-handle]');if(!handle)return;e.preventDefault();stage.setPointerCapture(e.pointerId);const p=point(e);paperCrop.start(handle.dataset.handle,p.x,p.y)};
 stage.onpointermove=e=>{if(!paperCrop.drag)return;e.preventDefault();const p=point(e);paperCrop.move(p.x,p.y);updatePaperCrop()};stage.onpointerup=stage.onpointercancel=()=>{paperCrop.drag=null};
 $('#cropWidth').oninput=e=>{paperCrop.size('w',Number(e.target.value)/100);updatePaperCrop()};$('#cropHeight').oninput=e=>{paperCrop.size('h',Number(e.target.value)/100);updatePaperCrop()};updatePaperCrop();
}
function updatePaperCrop(){if(!paperCrop||!$('#cropSelection'))return;const b=paperCrop.box,r=paperCrop.rect();Object.assign($('#cropSelection').style,{left:b.x*100+'%',top:b.y*100+'%',width:b.w*100+'%',height:b.h*100+'%'});$('#cropWidth').value=Math.round(b.w*100);$('#cropHeight').value=Math.round(b.h*100);$('#cropSize').textContent='纸张比例 '+r.width+' : '+r.height}

function quiz(){const a=M.assessment(assessmentId),q=a.questions[questionIndex],n=a.questions.length;return`<div class="tabs assessment-tabs">${['awareness','phq9'].map(id=>button(id==='phq9'?'PHQ-9':'美育觉察','assessment',id,'small '+(assessmentId===id?'active':''))).join('')}</div>${title(a.title,n+' 题 · '+a.period)}<p class="sub">${a.description}</p><div class="quiz-progress"><i style="width:${answers.filter(x=>x!==null).length/n*100}%"></i></div><div class="row"><span class="tiny" id="quizCount">已完成 ${answers.filter(x=>x!==null).length} / ${n}</span><span class="tag">第 ${questionIndex+1} 题</span></div><form id="quizForm"><section class="question" role="group" aria-labelledby="questionTitle"><h2 id="questionTitle"><span class="q-number">QUESTION ${String(questionIndex+1).padStart(2,'0')}</span>${q.text}</h2><div class="options">${a.options.map((s,i)=>`<label class="option"><input type="radio" name="answer" value="${i}" ${answers[questionIndex]===i?'checked':''}><span>${s}<small class="tiny">${i} 分</small></span></label>`).join('')}</div></section><div class="row">${button('← 上一题','quiz-prev',null,'small')}<span class="tiny">${questionIndex+1} / ${n}</span><button class="btn primary" type="submit">${questionIndex===n-1?'查看结果':'下一题 →'}</button></div></form>${notice(assessmentId==='phq9'?'PHQ-9 是筛查工具，不能仅凭分数作诊断。第 9 题的感受无论总分多少都值得及时寻求支持。':'每一种感受都值得被温柔对待。美育觉察结果不用于疾病筛查或诊断。')}${assessmentId==='phq9'?'<a class="tiny" href="'+M.phqSource+'" target="_blank" rel="noopener">查看 PHQ-9 中文原题与来源 ↗</a>':''}`}
function artReference(kind){const refs=M.artReferences[kind];modal(`<div class="row"><h2>${kind==='write'?'书法':'国画'}鉴赏与参考</h2>${button('返回创作','close',null,'small')}</div><p class="tiny">慢慢看，再随心落笔。欣赏与临写不必追求形似。</p>${refs.map(r=>`<article class="art-reference"><h3>${r.title}</h3><p class="sub">${r.intro}</p>${r.image?'<div class="reference-image"><img src="../assets/'+r.image+'" alt="'+r.title+'局部参考图"></div>':'<div class="reference-pending">山水作品图片待补充</div>'}<p><b>观赏</b> · ${r.observation}</p><p><b>试一试</b> · ${r.practice}</p></article>`).join('')}${button('回到我的画布','close',null,'primary full')}`)}

function findReport(id){return state().reports.find(r=>r.id===id)||state().reports[0]}
function result(id){const r=findReport(id);if(!r)return title('还没有觉察报告')+`<a class="btn primary" href="#test">开始自测</a>`;return`${title(r.title||'你的情绪参考','只为参考，不作诊断')}<p class="tiny">${date(r.time)}</p>${r.scaleId==='phq9'?'<div class="score-card"><strong>'+r.score+'<small> / 27</small></strong><p>PHQ-9 总分 · 参考区间 '+r.band+'</p><span class="tiny">分数不能独立确定诊断或安全风险</span></div>':'<canvas id="radar" class="radar" width="360" height="260" aria-label="情绪参考雷达图"></canvas>'}<div class="card"><p>${r.text}</p></div>${notice(r.note)}${r.safetyFlag?notice(esc(M.phqSupport),true):''}${r.scaleId==='phq9'?'<a class="btn" href="#experts">了解专业支持 →</a>':''}<div class="stack"><a class="btn primary" href="#write">去书法书写放松 →</a><a class="btn" href="#paint">去水墨创作表达 →</a><a class="btn" href="#chat">AI 情绪陪伴聊聊 →</a><a class="btn small" href="#profile">回个人中心</a>${button('删除这份本地报告','delete-report',r.id,'small danger')}</div>`}
function mountRadar(id){const r=findReport(id);if(r&&r.scaleId!=='phq9')B.radar($('#radar').getContext('2d'),360,260,r.values)}
async function chat(){if(!chatId||!state().sessions.some(s=>s.id===chatId))chatId=state().sessions[0]?.id||(await repo.newSession()).id;const s=state().sessions.find(s=>s.id===chatId);return`<div class="chat-page"><div class="row"><h1 style="font-size:22px">AI 情绪陪伴</h1>${button('新会话','chat-new',null,'small')}</div>${notice('⚠ AI 仅美育情绪陪伴，不做心理诊断；出现强烈痛苦请寻求可信任成年人或专业老师支持。',true)}<div class="chat-log" id="chatLog">${s.messages.map(m=>`<div class="bubble ${m.role==='assistant'?'assistant':''}">${esc(m.text)}<time>${date(m.time)}</time></div>`).join('')}${s.paused?`<div class="risk-block"><p>${M.riskNotice}</p><a class="btn primary full" href="#booking">了解专家咨询</a></div>`:''}</div><form id="chatForm" class="chat-input"><input id="chatText" name="text" maxlength="600" autocomplete="off" placeholder="聊聊创作、压力或此刻的感受…" aria-label="对话内容" ${s.paused?'disabled':''}><button class="btn primary" type="submit" ${s.paused?'disabled':''}>发送</button></form></div>`}
async function sendChat(text){if(chatBusy)return;chatBusy=true;const input=$('#chatText');if(input)input.disabled=true;try{const out=await repo.chat(chatId,text);await render();if(out.risk)modal(`<h2 class="red-text">先照顾好此刻的自己</h2><p>${esc(out.notice)}</p><div class="actions"><a class="btn primary" href="#booking" data-close-on-nav>了解专家咨询</a>${button('我知道了','close')}</div>`)}catch(e){error(e);if(input)input.disabled=false}finally{chatBusy=false}}
async function library(){const s=state(),items=workFilter==='report'?s.reports:s.works.filter(w=>workFilter==='all'||w.type===workFilter),per=4,total=Math.ceil(items.length/per);workPage=Math.max(0,Math.min(workPage,total-1));const cards=await Promise.all(items.slice(workPage*per,workPage*per+per).map(async w=>workFilter==='report'?`<button class="work" data-action="report" data-id="${w.id}"><div class="report-tile">觉</div><div class="info"><span class="tag">自测报告</span><time>${date(w.time)}</time><p>${esc(w.title||'美育觉察报告')} · 非诊断</p></div></button>`:`<button class="work" data-action="work" data-id="${w.id}"><img src="${await repo.media(w)}" alt="${w.type==='write'?'正念书法':'水墨画作'}"><div class="info"><span class="tag">${esc(w.emotion)}</span> <span class="tiny">${w.authorized?'已授权导师':'仅自己可见'}</span><time>${date(w.time)}</time><p>${esc(w.note||'让笔墨替我表达。')}</p></div></button>`));return`${title('我的情绪作品库','收藏每一次与自己的相遇')}<p class="sub">作品默认私密，主动授权后才会出现在导师面板。</p><div class="tabs">${[['all','全部作品'],['write','正念书法'],['paint','水墨画作'],['report','自测报告']].map(([id,t])=>`<button class="btn small ${workFilter===id?'active':''}" data-action="filter" data-id="${id}">${t}</button>`).join('')}</div>${cards.length?`<div class="works">${cards.join('')}</div>`:empty('还没有这一类记录，先去写一笔、画一画吧。')}<div class="pager">${button('← 上一页','works-prev',null,'small')}<span>${workPage+1} / ${Math.max(1,total)}</span>${button('下一页 →','works-next',null,'small')}</div>`}
async function workDetail(id,mentor=false){const w=state().works.find(w=>w.id===id);if(!w||mentor&&!w.authorized)throw Error('作品不存在或未授权');const image=await repo.media(w);modal(`<div class="modal-head"><h2>${w.type==='write'?'正念书法':'水墨画作'}</h2>${button('关闭','close',null,'small')}</div><img class="detail-image" src="${image}" alt="完整作品"><span class="tag">${esc(w.emotion)}</span><p class="tiny">${date(w.time)}</p><p style="white-space:pre-wrap">${esc(w.note||'此刻无言，笔墨已替我表达。')}</p>${w.comments.map(c=>`<div class="comment">美育评语：${esc(c.text)}<div class="tiny">${date(c.time)}</div></div>`).join('')}${mentor?`<form id="commentForm" data-id="${w.id}"><label class="field">美育评语（不使用心理诊断类文字）</label><textarea name="text" maxlength="300" required></textarea><button class="btn primary full" style="margin-top:12px">添加评语</button></form>`:`<label class="check"><input type="checkbox" data-auth="${w.id}" ${w.authorized?'checked':''}>授权导师查看此作品（可随时撤回）</label><div class="actions">${button('下载图片','download-work',id)}${button('删除作品','delete-work',id,'danger')}</div>`}`)}
function activityCard(a){return`<article class="card"><div class="row"><h3>${esc(a.title)}</h3><span class="tag">余 ${repo.remaining(a.id)} 名</span></div><p class="sub" style="margin-top:8px">${esc(a.time)}<br>${esc(a.place)}</p><p class="sub" style="margin:9px 0">${esc(a.intro)}</p>${button('预约这场团辅','book-activity',a.id,'primary full')}</article>`}
function booking(){return`${title('预约服务','线下见面，慢慢表达')}<div class="section-head"><h2>线下艺术团辅</h2><span class="tag">美育活动</span></div><p class="sub" style="margin-bottom:12px">艺术团辅属于美育活动，不等同于心理治疗。</p><div class="stack">${state().activities.map(activityCard).join('')}</div><div class="section-head"><h2>专家一对一咨询预约</h2></div><div class="card"><p class="sub">不提供线上实时心理咨询，具体咨询安排请通过机构正规渠道确认。</p><a class="btn primary full" style="margin-top:14px" href="#experts">查看全部专家 →</a></div>`}
function expertCard(e,manage=false){return`<article class="card"><div class="expert"><img class="avatar" src="../assets/${e.avatarImage?esc(e.avatarImage):'avatar-'+e.avatar%2+'.png'}" alt="专家头像"><div><h3>${esc(e.name)}</h3><span class="tag">${esc(e.title)}</span><p class="sub" style="margin-top:7px">${esc(e.specialty)}</p></div></div><p class="sub expert-bio" style="margin-top:10px">${esc(e.bio)}</p><p class="tiny" style="margin-top:12px">${e.slots.map(esc).join(' / ')}</p>${manage?`<div class="actions">${button('编辑资料','edit-expert',e.id)}${button(e.active?'停用':'启用','toggle-expert',e.id,e.active?'danger':'primary')}</div>`:button('查看时段与预约','book-expert',e.id,'primary full')}${!e.active?'<p class="red-text tiny">已停用，不出现在学生专家库</p>':''}</article>`}
function experts(){return`${title('心理咨询专家库','线下见面，安心表达')}${notice('本平台仅提供预约对接渠道，不提供线上实时心理咨询；预约成功后应参与线下面对面咨询。')}${assistCase?notice('正在为此工单填写预约记录。'):''}<div class="stack">${state().experts.filter(e=>e.active).map(e=>expertCard(e)).join('')||empty('暂无启用的专家')}</div>`}
function bookingForm(kind,id){const s=state(),a=kind==='activity'?s.activities.find(a=>a.id===id):s.experts.find(e=>e.id===id);if(!a)throw Error('内容不存在');const booked=kind==='expert'?s.bookings.filter(b=>b.expertId===id&&b.status!=='已取消').map(b=>b.slot):[];const available=kind==='expert'?a.slots.filter(t=>!booked.includes(t)):[];modal(`<div class="modal-head"><h2>${esc(kind==='activity'?a.title:a.name)}</h2>${button('关闭','close',null,'small')}</div>${kind==='expert'?`<p class="sub">${esc(a.bio)}</p>`:''}${notice('艺术团辅属于美育活动，不等同于心理治疗。')}<form id="bookingForm" data-kind="${kind}" data-id="${id}">${kind==='expert'?`<label class="field" for="slot">可约时段</label><select id="slot" name="slot" required>${available.map(t=>`<option>${esc(t)}</option>`).join('')}</select>${available.length?'':'<p class="red-text">时段已约满</p>'}`:`<p class="sub">${esc(a.time)} · ${esc(a.place)}</p>`}<label class="field" for="bookName">称呼（可用化名）</label><input id="bookName" name="name" type="text" maxlength="20" value="${esc(assistCase?(s.cases.find(c=>c.id===assistCase)?.userId||s.profile.nickname):s.profile.nickname)}" required><label class="field" for="bookGrade">年级 / 基础信息（选填）</label><input id="bookGrade" type="text" name="grade" maxlength="20" value="${esc(s.profile.grade)}"><label class="field" for="bookContact">联系方式（选填）</label><input id="bookContact" type="text" name="contact" maxlength="50" placeholder="填写方便联系的方式"><label class="field" for="bookRequest">想表达的感受 / 预约诉求（选填）</label><textarea id="bookRequest" name="request" maxlength="300"></textarea><label class="check"><input type="checkbox" name="consent" required>我已核对预约信息。</label><button class="btn primary full" ${kind==='expert'&&!available.length?'disabled':''}>保存预约记录</button></form>`)}
function profile(){const s=state();return`${title('个人中心','把每一次感受，温柔珍藏')}<div class="profile-card" style="margin-top:16px"><div class="profile-glyph">我</div><div><h2>${esc(s.profile.nickname)}</h2><p class="tiny">用户 ${esc(s.profile.id.slice(-8))}</p><p class="sub">${esc(s.profile.grade)}</p></div></div><div class="stats"><div class="stat"><b>${s.works.length}</b><span>笔墨作品</span></div><div class="stat"><b>${s.reports.length}</b><span>觉察报告</span></div><div class="stat"><b>${s.bookings.length}</b><span>预约记录</span></div></div><div class="menu">${button('个人基础信息 <span>›</span>','profile-edit')}<a href="#library">我的作品库 <span>›</span></a>${button('自测报告回看 <span>›</span>','my-reports')}${button('AI 对话会话管理 <span>›</span>','my-chats')}${button('我的预约记录 <span>›</span>','my-bookings')}${button('工单留言 <span>›</span>','my-messages')}${button('隐私设置 <span>›</span>','privacy')}${button('项目介绍与完整免责声明 <span>›</span>','about')}<a href="#experts">专家库 <span>›</span></a><a href="#admin-risk">导师工作台 <span>›</span></a></div>${notice('清除缓存前，请备份重要作品。')}`}
function myBookings(){const s=state();modal(`<div class="modal-head"><h2>我的预约记录</h2>${button('关闭','close',null,'small')}</div>${s.bookings.filter(b=>b.userId===s.profile.id).map(b=>`<div class="list-item"><span class="tag">${esc(b.status)}</span><h3>${esc(b.title)}</h3><p class="sub">${esc(b.slot)} · ${b.kind==='activity'?'团辅':'专家咨询'}<br>回执号 ${esc(b.id)}</p>${!['已取消','已完成'].includes(b.status)?button('取消预约','cancel-booking',b.id,'small danger'):''}</div>`).join('')||empty('还没有预约记录')}`)}
function myChats(){modal(`<div class="modal-head"><h2>AI 会话管理</h2>${button('关闭','close',null,'small')}</div>${state().sessions.map(s=>`<div class="list-item"><p>${date(s.time)} ${s.paused?'<span class="tag red">已暂停</span>':''}</p><p class="sub">${s.messages.length} 条消息</p><div class="actions">${button('查看会话','open-chat',s.id)}${button('删除会话','delete-chat',s.id,'danger')}</div></div>`).join('')||empty('还没有会话')}`)}
function adminRisk(){const s=state(),cases=s.cases.slice().sort((a,b)=>(a.status==='处理完成')-(b.status==='处理完成')||Number(a.demo)-Number(b.demo)||new Date(b.time)-new Date(a.time));return`${adminNav()}${title('高危关键词工单队列','关键词触发 · 待人工核验')}${notice('关键词触发仅作关注提示，不等同于专业风险评估。',true)}<div class="admin-grid">${cases.map(c=>`<article class="card risk-card ${c.status==='处理完成'?'finished':''}"><div class="row"><span class="tag red">${esc(c.status)}</span><span class="tiny">${c.demo?'预置案例':'会话触发'}</span></div><h3 style="margin-top:10px">${esc(c.userId)}</h3><p class="tiny">${date(c.time)}</p><p class="tiny">${c.tags.map(esc).join(' · ')}</p><p class="sub" style="margin-top:8px">${esc(c.transcript[c.transcript.length-1]?.text||'')}</p><div class="actions">${button('查看与跟进','case',c.id,'danger')}${button('协助预约','assist',c.id)}</div></article>`).join('')||empty('暂无工单')}</div>`}
function caseDetail(id){const c=state().cases.find(c=>c.id===id);if(!c)throw Error('工单不存在');modal(`<div class="modal-head"><h2>工单跟进</h2>${button('关闭','close',null,'small')}</div><span class="tag red">${esc(c.status)}</span><p class="sub">用户 ${esc(c.userId)}<br>${date(c.time)} · ${c.demo?'预置案例':'关键词匹配'}</p><div class="case-transcript">${c.transcript.map(m=>`<p><b>${m.role==='user'?'用户':'笔墨陪伴'}：</b>${esc(m.text)}</p>`).join('')}</div>${c.notes.map(n=>`<div class="comment">${esc(n.text)}<div class="tiny">${date(n.time)}</div></div>`).join('')}<form id="caseNoteForm" data-id="${c.id}"><label class="field" for="caseNote">站内留言</label><textarea id="caseNote" name="text" maxlength="400" required></textarea><button class="btn full" style="margin-top:10px">保存留言</button></form><div class="actions">${button('标记跟进中','case-progress',c.id)}${button('处理完成','case-done',c.id)}</div>${button('协助预约专家','assist',c.id,'primary full')}`)}
function adminBooking(){return`${adminNav()}${title('预约工单管理','团辅报名 · 专家预约')}<div class="admin-grid">${state().bookings.map(b=>`<article class="card"><div class="row"><span class="tag">${esc(b.status)}</span><span class="tiny">${b.kind==='activity'?'团辅报名':'专家咨询'}</span></div><h3>${esc(b.title)}</h3><p class="sub">${esc(b.name)} · ${esc(b.grade)}<br>${esc(b.slot)}<br>${esc(b.contact||'未填写联系方式')}</p><p class="sub">${esc(b.request)}</p><div class="actions">${button('确认','booking-confirm',b.id)}${button('完成','booking-done',b.id)}${button('取消','cancel-booking',b.id,'danger')}</div></article>`).join('')||empty('暂无预约工单')}</div>`}
function adminExperts(){return`${adminNav()}<div class="row">${title('专家库管理','姓名 · 方向 · 排班')}${button('＋ 新增','new-expert',null,'primary')}</div><p class="sub" style="margin:12px 0">停用后不再出现在学生端专家库。</p><div class="admin-grid">${state().experts.map(e=>expertCard(e,true)).join('')}</div>`}
function expertForm(id){const e=state().experts.find(e=>e.id===id)||{name:'',title:'书画美育',specialty:'',bio:'请填写服务方向与预约说明。',slots:[],active:true};modal(`<div class="modal-head"><h2>${id?'编辑专家':'新增专家'}</h2>${button('关闭','close',null,'small')}</div><form id="expertForm" data-id="${id||''}"><label class="field">姓名</label><input name="name" type="text" value="${esc(e.name)}" required maxlength="30"><label class="field">身份标签</label><input name="title" type="text" value="${esc(e.title)}" maxlength="80"><label class="field">擅长方向</label><input name="specialty" type="text" value="${esc(e.specialty)}" maxlength="100"><label class="field">资料说明</label><textarea name="bio" maxlength="400">${esc(e.bio)}</textarea><label class="field">可约时段（每行一个，例如 2026-11-01 10:00）</label><textarea name="slots" required>${esc(e.slots.join('\n'))}</textarea><label class="check"><input name="active" type="checkbox" ${e.active?'checked':''}>启用此专家</label><button class="btn primary full">保存专家资料</button></form>`)}
async function adminWorks(){const list=repo.authorizedWorks(),cards=await Promise.all(list.map(async w=>`<button class="work" data-action="mentor-work" data-id="${w.id}"><img src="${await repo.media(w)}" alt="已授权作品"><div class="info"><span class="tag">主动授权</span><time>${date(w.time)}</time><p>${esc(w.emotion)} · ${esc(w.userId.slice(-8))}</p></div></button>`));return`${adminNav()}${title('学员授权作品','仅查看主动开放的笔墨')}${notice('仅显示学生主动授权的作品。评语限于美育、构图、笔墨与表达，不得进行心理诊断。撤回授权后，作品即从此面板移除。')}<div class="works">${cards.join('')}</div>${cards.length?'':empty('目前没有学员授权的作品，私密作品不会出现在这里。')}`}
async function action(name,id,target){switch(name){
 case'ink-replay':runInkPresentation(true);break;case'ink-continue':closeModal();break;case'ink-library':closeModal();workFilter='write';workPage=0;navigate('library');break;
 case'close':closeModal();break;case'enter':navigate('home');break;case'route-booking':navigate('booking');break;case'event':showEvent(+id,true);break;
 case'music':if(musicPlaying)pauseWritingMusic(true);else await playWritingMusic(true);break;
 case'scroll-mode':{const on=$('#drawing').classList.toggle('scrollable');$('#paperScroll').classList.toggle('locked',!on);target.textContent=on?'切换为书写':'切换为滚动';break}
 case'paper-crop':openPaperCrop();break;case'crop-ratio':paperCrop.reset(id==='full'?null:Number(id));updatePaperCrop();break;case'crop-confirm':engine.crop(paperCrop.rect());closeModal();paperCrop=null;toast('纸张已裁切，可撤销恢复');break;
 case'photo-slide':showPhoto(Number(id),true);break;
 case'undo':if(stampEditing)finishStampPreview();else engine.undo();break;case'redo':engine.redo();break;case'clear':modal(`<h2>重新铺一张素笺？</h2><p>尚未保存的画面将被清空。</p><div class="actions">${button('继续创作','close')}${button('确认清空','clear-confirm',null,'danger')}</div>`);break;case'clear-confirm':if(stampEditing)finishStampPreview();engine.clear();closeModal();break;
 case'eraser':engine.configure({eraser:!engine.settings.eraser});target.classList.toggle('primary',engine.settings.eraser);target.textContent=engine.settings.eraser?'正在擦除':'橡皮擦';break;
 case'material':engine.addMaterial(id);toast('在画布上拖动到想要的位置，松手放置');break;
 case'stamp':modal(`<h2>加盖朱文小印</h2><p class="sub">选择印章后，可调整大小，并在纸面上自由选择位置。</p><div class="actions">${['静心','安然','自在'].map(t=>button(t,'stamp-pick',t)).join('')}</div>${button('取消','close',null,'full')}`);break;case'stamp-pick':closeModal();startStampPreview(id);break;case'stamp-cancel':finishStampPreview();break;case'stamp-confirm':if(engine.drag){engine.placeMaterial(engine.drag.x,engine.drag.y);finishStampPreview();toast('已盖印，可撤销')}break;
 case'art-reference':artReference(id);break;
 case'assessment':if(id!==assessmentId){assessmentId=id==='phq9'?'phq9':'awareness';answers=Array(M.assessment(assessmentId).questions.length).fill(null);questionIndex=0;await render()}break;
 case'paint-info':modal(`<h2>以墨为语</h2><p>随心画，无对错，笔墨即心情。试试润水笔与枯笔刷，叠加的墨色会自然加深。素材选中后可在画布上拖动放置；橡皮擦会柔和擦除笔墨，保留纸底。</p>${button('开始创作','close',null,'primary full')}`);break;
 case'save-art':if(stampEditing)throw Error('请先确认盖印或取消印章');if(!engine.hasInk())throw Error('先落下一笔，再收藏这份心情吧');if(engine.drag)throw Error('请先在画布上放置当前素材');modal(`<h2>收藏这一刻</h2><form id="artForm"><label class="field" for="artMood">此刻的情绪标签</label><select id="artMood" name="emotion">${M.moods.map(m=>`<option>${m}</option>`).join('')}</select><label class="field" for="artNote">简短心情备注（选填）</label><textarea id="artNote" name="note" maxlength="300" placeholder="这幅画 / 这些字，让我想到……"></textarea><p class="tiny">作品默认仅自己可见，可在作品库主动授权导师。</p><div class="actions">${button('继续创作','close')}<button class="btn primary">保存到作品库</button></div></form>`);break;
 case'quiz-prev':if(questionIndex>0){questionIndex--;await render()}break;
 case'delete-report':modal(`<h2>删除这份报告？</h2><p>自测记录将被删除。</p><div class="actions">${button('保留','close')}${button('确认删除','delete-report-confirm',id,'danger')}</div>`);break;case'delete-report-confirm':await repo.deleteReport(id);closeModal();navigate('library');workFilter='report';break;
 case'chat-new':chatId=(await repo.newSession()).id;await render();break;
 case'filter':workFilter=id;workPage=0;await render();break;case'works-prev':workPage=Math.max(0,workPage-1);await render();break;case'works-next':workPage++;await render();break;case'report':navigate('result',{id});break;case'work':await workDetail(id);break;case'mentor-work':await workDetail(id,true);break;
 case'download-work':{const w=state().works.find(w=>w.id===id),a=document.createElement('a');a.href=await repo.media(w);a.download='墨润心源-'+id+'.jpg';a.click();toast('图片已生成，手机也可长按图片保存');break}
 case'delete-work':modal(`<h2>删除这幅作品？</h2><p>图片、授权与评语会被删除。</p><div class="actions">${button('保留','close')}${button('确认删除','delete-work-confirm',id,'danger')}</div>`);break;case'delete-work-confirm':await repo.deleteWork(id);closeModal();await render();toast('作品已删除');break;
 case'book-activity':bookingForm('activity',id);break;case'book-expert':bookingForm('expert',id);break;
 case'profile-edit':{const p=state().profile;modal(`<h2>个人基础信息</h2><p class="sub">可以使用你喜欢的称呼。</p><form id="profileForm"><label class="field">称呼</label><input name="nickname" type="text" value="${esc(p.nickname)}" maxlength="20" required><label class="field">年级</label><select name="grade">${['初中','高中','其他'].map(g=>`<option ${p.grade===g?'selected':''}>${g}</option>`).join('')}</select><label class="field">联系方式（选填）</label><input name="contact" type="text" value="${esc(p.contact)}" maxlength="50"><div class="actions">${button('取消','close')}<button class="btn primary">保存</button></div></form>`);break}
 case'my-reports':workFilter='report';closeModal();navigate('library');break;case'my-bookings':myBookings();break;case'my-chats':myChats();break;
 case'open-chat':chatId=id;closeModal();navigate('chat');break;case'delete-chat':modal(`<h2>删除这次会话？</h2><p>会话及其关联的工单也将删除。</p><div class="actions">${button('保留','close')}${button('确认删除','delete-chat-confirm',id,'danger')}</div>`);break;case'delete-chat-confirm':await repo.deleteSession(id);if(chatId===id)chatId=null;myChats();toast('会话已删除');break;
 case'privacy':modal(`<h2>隐私设置</h2><p class="sub">请选择作品的默认可见范围。</p><label class="check"><input id="privacyDefault" type="checkbox" ${state().profile.privateByDefault?'checked':''}>新作品默认仅自己可见</label><p class="tiny">关闭后，新保存的作品会默认授权导师查看；已有作品不变。每幅作品仍可单独撤回授权。</p>${button('保存设置','privacy-save',null,'primary full')}<div class="separator"></div>${button('清空 V2 数据','reset',null,'danger full')}`);break;case'privacy-save':await repo.privacy($('#privacyDefault').checked);closeModal();toast('隐私设置已保存');break;case'reset':modal(`<h2>清空全部 V2 记录？</h2><p>作品、报告、对话、预约与工单将被删除，演示专家和预置案例会恢复。V1 数据不受影响。</p><div class="actions">${button('取消','close')}${button('确认清空','reset-confirm',null,'danger')}</div>`);break;case'reset-confirm':await repo.reset();chatId=null;closeModal();await render();toast('V2 数据已重置');break;
 case'about':modal(`<h2>墨润心源</h2><p>以笔墨润心境，以美育疗情绪。</p><p style="margin:12px 0">本项目是线下初高中书画艺术疗愈团体辅导的线上配套 Demo，以传统书画美育和表达性艺术理念帮助青少年觉察感受、练习表达。</p>${notice(M.disclaimer,true)}<p class="sub">美育觉察问卷为自编问题；PHQ-9 为筛查参考，不作诊断。本项目为大学生竞赛作品。人物、活动与排班为演示资料；实际服务请通过机构正规渠道确认。对话采用预设问答。记录保存在当前设备，清除缓存前请备份重要作品。</p><p class="sub" style="margin-top:12px">未成年人遇到强烈痛苦时，请向可信任的成年人或专业人员求助。</p><p class="tiny" style="margin:14px 0">第十四届全国大学生数字媒体科技作品及创意竞赛参赛演示，非商用。</p>${button('知道了','close',null,'primary full')}`);break;
 case'my-messages':{const cases=state().cases.filter(c=>c.userId===state().profile.id);modal(`<h2>工单留言</h2>${cases.map(c=>`<div class="list-item"><span class="tag red">${c.status}</span><p class="tiny">${date(c.time)}</p>${c.notes.map(n=>`<p class="sub">${esc(n.text)}</p>`).join('')||'<p class="sub">暂无导师留言。</p>'}</div>`).join('')||empty('暂无工单消息')}${button('关闭','close',null,'full')}`);break}
 case'case':caseDetail(id);break;case'case-progress':await repo.caseStatus(id,'跟进中');caseDetail(id);await render();break;case'case-done':await repo.caseStatus(id,'处理完成');caseDetail(id);await render();break;
 case'assist':assistCase=id;closeModal();navigate('experts');break;case'booking-confirm':await repo.bookingStatus(id,'已确认');await render();break;case'booking-done':await repo.bookingStatus(id,'已完成');await render();break;case'cancel-booking':await repo.bookingStatus(id,'已取消');if(current==='profile')myBookings();else await render();break;
 case'new-expert':expertForm();break;case'edit-expert':expertForm(id);break;case'toggle-expert':await repo.toggleExpert(id);await render();break;
 }}
document.addEventListener('click',e=>{const t=e.target.closest('[data-action]');if(t){e.preventDefault();Promise.resolve(action(t.dataset.action,t.dataset.id,t)).catch(error)}if(e.target.closest('[data-close-on-nav]'))closeModal()});
document.addEventListener('change',e=>{if(e.target.dataset.auth)repo.authorize(e.target.dataset.auth,e.target.checked).then(()=>toast(e.target.checked?'已授权导师查看':'已撤回授权')).catch(err=>{const saved=state().works.find(w=>w.id===e.target.dataset.auth);e.target.checked=!!(saved&&saved.authorized);error(err)});if(e.target.name==='answer'){answers[questionIndex]=Number(e.target.value);$('.quiz-progress i').style.width=answers.filter(x=>x!==null).length/answers.length*100+'%';$('#quizCount').textContent='已完成 '+answers.filter(x=>x!==null).length+' / '+answers.length;if(assessmentId==='phq9'&&questionIndex===8&&answers[8]>0)modal('<h2>请让身边的人陪伴你</h2><p>'+esc(M.phqSupport)+'</p>'+button('我知道了，继续填写','close',null,'primary full'))}});
document.addEventListener('input',e=>{if(e.target.id==='chatText'&&M.matchRisk(e.target.value).length)sendChat(e.target.value).catch(error)});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,values=Object.fromEntries(new FormData(f));const submit=f.querySelector('button[type=submit],button:not([type])');if(submit)submit.disabled=true;try{switch(f.id){
 case'quizForm':if(answers[questionIndex]===null)throw Error('先选择这一题的答案吧');if(questionIndex<answers.length-1){questionIndex++;await render()}else{const r=await (assessmentId==='phq9'?repo.addPhqReport(answers):repo.addReport(answers));answers=Array(M.assessment(assessmentId).questions.length).fill(null);questionIndex=0;navigate('result',{id:r.id})}break;
 case'chatForm':await sendChat(values.text);break;
 case'artForm':{const img=engine.exportCanvas().toDataURL('image/jpeg',.84);await repo.addWork({type:current,emotion:values.emotion,note:values.note},img);if(current==='write')showInkPresentation();else{closeModal();navigate('library');toast('作品已保存到作品库')}break}
 case'bookingForm':{const b=await repo.book({...values,kind:f.dataset.kind,activityId:f.dataset.kind==='activity'?f.dataset.id:null,expertId:f.dataset.kind==='expert'?f.dataset.id:null,consent:values.consent==='on',caseId:assistCase});if(assistCase){await repo.caseNote(assistCase,'预约记录已生成，回执号：'+b.id);assistCase=null}modal(`<div class="success-receipt"><span class="glyph">约</span><h2>预约记录已保存</h2><p>${esc(b.title)}<br>${esc(b.slot)}</p><p class="tiny">回执号 ${esc(b.id)}<br>状态：待确认</p></div><div class="actions">${button('查看我的预约','my-bookings')}${button('关闭','close')}</div>`);break}
 case'profileForm':await repo.updateProfile(values);closeModal();await render();toast('个人信息已保存');break;
 case'commentForm':await repo.comment(f.dataset.id,values.text);await workDetail(f.dataset.id,true);toast('美育评语已保存');break;
 case'caseNoteForm':await repo.caseNote(f.dataset.id,values.text);caseDetail(f.dataset.id);toast('留言已保存');break;
 case'expertForm':await repo.saveExpert({...values,id:f.dataset.id||null,active:values.active==='on'});closeModal();await render();toast('专家资料已保存');break;
 }}catch(e){error(e)}finally{if(submit&&submit.isConnected)submit.disabled=false}});
window.addEventListener('hashchange',()=>{closeModal();render().catch(error)});document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseWritingMusic();else if(current==='write'&&musicWanted&&!musicPausedByUser)playWritingMusic()});window.addEventListener('pagehide',()=>pauseWritingMusic());
// Every document entry starts at the cover, including saved links to other sections.
history.replaceState(null,'',location.pathname+location.search+'#splash');
// Returning from another site may restore this document from the browser cache.
window.addEventListener('pageshow',event=>{if(event.persisted){closeModal();history.replaceState(null,'',location.pathname+location.search+'#splash');render().catch(error)}});
repo.init().then(()=>render()).catch(e=>{$('#main').innerHTML=`<h1>本地存储暂不可用</h1><p>${esc(e.message)}</p><p>请在允许本地存储的普通浏览器环境中重试。</p>`});
